const DEFAULT_CONSOLIDATION_MIN_INTERVAL_SECS: u64 = 3_600;

/// Current unix time in whole seconds.
pub fn now_unix() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

/// High-level facade over the graph store and the ingestion pipeline.
pub struct MindLeak {
    store: GraphStore,
    consolidation_min_interval_secs: u64,
    embedder: Box<dyn embed::TextEmbedder>,
    recall_floor: f64,
    /// The checkout this process serves, used to make incoming absolute paths
    /// repo-relative. Injected rather than reached for: the core has no business
    /// knowing where on disk it is, and tests must be able to set it.
    workspace_root: Option<String>,
}

// The async maintenance worker (`mindleak-mcp`) moves a `MindLeak` into
// `std::thread::spawn`, so `MindLeak` must stay `Send`. This fails to compile if
// a field regresses that (e.g. a non-thread-safe embedder) — the `Send + Sync`
// bound on `embed::TextEmbedder` is what keeps the boxed embedder `Send`.
const _: fn() = || {
    fn assert_send<T: Send>() {}
    assert_send::<MindLeak>();
};

impl MindLeak {
    /// Open (or create) a MindLeak database at `path`.
    pub fn open(path: &str) -> Result<Self> {
        Ok(MindLeak {
            store: GraphStore::new(db::open(path)?),
            consolidation_min_interval_secs: DEFAULT_CONSOLIDATION_MIN_INTERVAL_SECS,
            embedder: Box::new(embed::Embedder::default()),
            recall_floor: config::DEFAULT_RECALL_FLOOR,
            workspace_root: None,
        })
    }

    /// Open an ephemeral in-memory graph (tests / tooling).
    pub fn open_in_memory() -> Result<Self> {
        Ok(MindLeak {
            store: GraphStore::new(db::open_in_memory()?),
            consolidation_min_interval_secs: DEFAULT_CONSOLIDATION_MIN_INTERVAL_SECS,
            embedder: Box::new(embed::Embedder::default()),
            recall_floor: config::DEFAULT_RECALL_FLOOR,
            workspace_root: None,
        })
    }

    /// Declare the checkout this process serves, so absolute paths from editor
    /// sensors collapse onto the same repo-relative node ids the rest of the
    /// fleet writes.
    ///
    /// Every worktree of one repository shares a single graph (ADR-0038), so a
    /// path left absolute splits one file across as many identities as there are
    /// checkouts. Measured before this existed: **871 of 6,144 nodes carried
    /// absolute ids across 7 worktrees, and 590 files existed under two
    /// identities at once** -- including `AGENTS.md`. That splits reinforcement
    /// (so real signal decays like a one-off), hides collisions from
    /// `check_overlap`, and leaves governed bindings covering only one spelling.
    pub fn with_workspace_root(mut self, root: impl Into<String>) -> Self {
        let root = root.into();
        self.workspace_root = (!root.trim().is_empty()).then_some(root);
        self
    }

    /// Make a caller-supplied path repo-relative for stable node ids.
    pub(crate) fn repo_relative(&self, path: &str) -> String {
        ingest::repo_relative(path, self.workspace_root.as_deref())
    }

    /// Collapse node ids that spell their path absolutely under this checkout
    /// onto the repo-relative id the rest of the fleet writes, merging the two
    /// halves' history rather than choosing between them.
    ///
    /// A no-op when no workspace root was declared, and idempotent: a second
    /// pass finds nothing left to collapse. Cheap enough to run at startup,
    /// which is what keeps the graph healing itself if any producer ever writes
    /// an absolute id again.
    pub fn repair_workspace_paths(&self) -> Result<graph::RepairOutcome> {
        match self.workspace_root.as_deref() {
            Some(root) => self.store.repair_workspace_paths(root),
            None => Ok(graph::RepairOutcome::default()),
        }
    }

    /// Override the immutable decay policy resolved by the hosting process.
    pub fn with_decay_policy(mut self, decay_policy: config::DecayPolicy) -> Self {
        self.store = self.store.with_decay_policy(decay_policy);
        self
    }

    pub fn with_working_set_size(mut self, size: usize) -> Self {
        self.store = self.store.with_working_set_size(size);
        self
    }

    /// Override the cosine floor below which `recall` returns nothing (ADR-0053).
    pub fn with_recall_floor(mut self, floor: f64) -> Self {
        self.recall_floor = floor.clamp(config::MIN_RECALL_FLOOR, config::MAX_RECALL_FLOOR);
        self
    }

    pub fn with_consolidation_min_interval(mut self, seconds: u64) -> Self {
        self.consolidation_min_interval_secs = seconds.clamp(60, 86_400);
        self
    }

    /// Override the semantic-recall embedding backend (ADR-0008). Defaults to a
    /// local `/v1/embeddings` client; tests inject a deterministic or unreachable
    /// embedder so the index→recall→seed path is exercised without a live model.
    pub fn with_embedder(mut self, embedder: Box<dyn embed::TextEmbedder>) -> Self {
        self.embedder = embedder;
        self
    }

    pub fn store(&self) -> &GraphStore {
        &self.store
    }
}

